# ---------------- 7. PARACHUTES AND CLIFFS ----------------
dict(text="Part seven. Parachutes and cliffs.", sfx='whoosh', pause=0.4,
     scene=dict(type='chapter', bg='red', num='7', kicker='Part', text='Parachutes\nand cliffs', tile='paper', accent='gold')),
